// Предполагаемый API @jinx-ui/react (примитивы и сигнатуры onChange(value)) — сверьте с документацией пакета.
import { useCallback, useState } from 'react';
import {
  Badge,
  Card,
  Divider,
  Field,
  SegmentedControl,
  Select,
  Slider,
  Stack,
  Switch,
  Text,
  Title,
} from '@jinx-ui/react';

export type ThemeMode = 'light' | 'dark' | 'system';
export type FontFamily = 'system' | 'inter' | 'mono';

export interface AppearanceSettings {
  theme: ThemeMode;
  scale: number;
  dense: boolean;
  font: FontFamily;
}

export interface AppearanceSettingsScreenProps {
  initialValue?: Partial<AppearanceSettings>;
  onChange: (value: AppearanceSettings) => void;
}

const DEFAULTS: AppearanceSettings = {
  theme: 'system',
  scale: 100,
  dense: false,
  font: 'system',
};

const THEME_LABELS: Record<ThemeMode, string> = {
  light: 'Светлая',
  dark: 'Тёмная',
  system: 'Системная',
};

const THEME_OPTIONS = (Object.keys(THEME_LABELS) as ThemeMode[]).map((value) => ({
  value,
  label: THEME_LABELS[value],
}));

const FONT_OPTIONS: Array<{ value: FontFamily; label: string }> = [
  { value: 'system', label: 'Системный' },
  { value: 'inter', label: 'Inter' },
  { value: 'mono', label: 'Моноширинный' },
];

const SCALE_MIN = 80;
const SCALE_MAX = 140;

function AppearanceSettingsScreen({ initialValue, onChange }: AppearanceSettingsScreenProps) {
  const [settings, setSettings] = useState<AppearanceSettings>({ ...DEFAULTS, ...initialValue });

  const update = useCallback(
    (patch: Partial<AppearanceSettings>) => {
      setSettings((prev) => {
        const next = { ...prev, ...patch };
        onChange(next);
        return next;
      });
    },
    [onChange],
  );

  return (
    <Card style={{ padding: 'var(--jx-space-6)' }}>
      <Stack direction="vertical" style={{ gap: 'var(--jx-space-6)' }}>
        <Stack
          direction="horizontal"
          align="center"
          justify="space-between"
          style={{ gap: 'var(--jx-space-3)' }}
        >
          <Title level={2}>Внешний вид</Title>
          <Badge>{THEME_LABELS[settings.theme]}</Badge>
        </Stack>

        <Field label="Тема" hint="Применяется ко всему интерфейсу">
          <SegmentedControl
            fullWidth
            value={settings.theme}
            options={THEME_OPTIONS}
            onChange={(theme: ThemeMode) => update({ theme })}
          />
        </Field>

        <Field label="Масштаб интерфейса">
          <Stack direction="vertical" style={{ gap: 'var(--jx-space-2)' }}>
            <Slider
              min={SCALE_MIN}
              max={SCALE_MAX}
              step={5}
              value={settings.scale}
              onChange={(scale: number) => update({ scale })}
            />
            <Stack direction="horizontal" justify="space-between">
              <Text tone="muted" size="sm">{SCALE_MIN}%</Text>
              <Text weight="medium">{settings.scale}%</Text>
              <Text tone="muted" size="sm">{SCALE_MAX}%</Text>
            </Stack>
          </Stack>
        </Field>

        <Switch
          label="Плотная вёрстка"
          description="Уменьшает отступы между элементами"
          checked={settings.dense}
          onChange={(dense: boolean) => update({ dense })}
        />

        <Divider />

        <Stack direction="vertical" style={{ gap: 'var(--jx-space-4)' }}>
          <Title level={3}>Ещё</Title>
          <Field label="Шрифт">
            <Select
              value={settings.font}
              options={FONT_OPTIONS}
              onChange={(font: FontFamily) => update({ font })}
            />
          </Field>
        </Stack>
      </Stack>
    </Card>
  );
}

export default AppearanceSettingsScreen;

